package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import java.util.zip.ZipException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class X7875_NewUnix_equals_TriageGen0Test {

    /**
     * Helper method to set private fields via reflection since the provided 
     * class description implies uid and gid are used in equals but 
     * doesn't provide setters for the objects themselves (only long values).
     * Based on the equals method: uid and gid are objects (likely Long or similar).
     */
    private void setFields(X7875_NewUnix target, int version, Object uid, Object gid) throws Exception {
        Field versionField = X7875_NewUnix.class.getDeclaredField("version");
        versionField.setAccessible(true);
        versionField.set(target, version);

        Field uidField = X7875_NewUnix.class.getDeclaredField("uid");
        uidField.setAccessible(true);
        uidField.set(target, uid);

        Field gidField = X7875_NewUnix.class.getDeclaredField("gid");
        gidField.setAccessible(true);
        gidField.set(target, gid);
    }

    @Test
    public void testEquals_SameObject() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        setFields(x1, 1, 1000L, 1000L);

        Assert.assertTrue(x1.equals(x1));
    }

    @Test
    public void testEquals_Null() {
        X7875_NewUnix x1 = new X7875_NewUnix();
        Assert.assertFalse(x1.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        X7875_NewUnix x1 = new X7875_NewUnix();
        String s = "not an X7875_NewUnix";
        Assert.assertFalse(x1.equals(s));
    }

    @Test
    public void testEquals_AllFieldsMatch() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setFields(x1, 2, 500L, 500L);
        setFields(x2, 2, 500L, 500L);

        Assert.assertTrue(x1.equals(x2));
        Assert.assertTrue(x2.equals(x1));
    }

    @Test
    public void testEquals_DifferentVersion() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setFields(x1, 1, 500L, 500L);
        setFields(x2, 2, 500L, 500L);

        Assert.assertFalse(x1.equals(x2));
    }

    @Test
    public void testEquals_DifferentUid() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setFields(x1, 1, 1000L, 500L);
        setFields(x2, 1, 2000L, 500L);

        Assert.assertFalse(x1.equals(x2));
    }

    @Test
    public void testEquals_DifferentGid() throws Exception {
        X7875_NewUnix x1 = new X7875_NewUnix();
        X7875_NewUnix x2 = new X7875_NewUnix();

        setFields(x1, 1, 500L, 1000L);
        setFields(x2, 1, 500L, 2000L);

        Assert.assertFalse(x1.equals(x2));
    }
}
